 where j.owner_id=(p->>'ownerId')::uuid and j.project_id=(p->>'projectId')::uuid and j.id=(p->>'id')::uuid;
$function$
CREATE OR REPLACE FUNCTION public.contractor_ai_source_revision(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actual text;project uuid=(p->>'projectId')::uuid;target uuid=(p->>'targetId')::uuid;
begin
 if p->>'type'='DOCUMENT_ANALYSIS' then select xmin::text into actual from public.documents where id=target and project_id=project;
 elsif p->>'type'='SCAN_FINDING' then select xmin::text into actual from public.contradictions where id=target and project_id=project;
 elsif p->>'type'='SCAN_STATE' then select xmin::text into actual from public.document_scan_state where id=target and project_id=project;
 elsif p->>'type'='PRICING_EVIDENCE' then select xmin::text into actual from public.pricing_ledger where id=target and project_id=project;
 else raise exception 'AI_EFFECT_INVALID';end if;
 return to_jsonb(coalesce(actual,'new'));
end;$function$
CREATE OR REPLACE FUNCTION public.guard_project_correspondence_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if coalesce(current_setting('contractorsystem.correspondence_write',true),'')<>'1' then raise exception 'Use correspondence workflow' using errcode='42501';end if;
 return new;
end;$function$
CREATE OR REPLACE FUNCTION public.guard_projects_budget_read_model()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.budget IS DISTINCT FROM OLD.budget
     AND CURRENT_USER NOT IN ('postgres', 'service_role', 'supabase_admin') THEN
    RAISE EXCEPTION 'Project budget can only be changed through the verified financial baseline flow';
  END IF;

  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, full_name, company_name, role)
  VALUES (
    new.id,
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'company_name',
    'contractor'
  );
  RETURN new;
END;
$function$
CREATE OR REPLACE FUNCTION public.is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND role IN ('admin', 'super_admin')
  );
